def inventory():
    rows = []
    for group, (title, backend, frontend, api, tables, criteria) in GROUPS.items():
        for number, behavior in enumerate(criteria.split('|'), 1):
            rows.append(dict(id=f'{group}.{number:02}', group=group, expected=behavior, title=title,
                backend='app/intent_radar/'+backend, frontend='dashboard/components/intent-radar/'+frontend,
                api=api, database=tables, status='IMPLEMENTED BUT NOT VERIFIED',
                actual='Inventory created before repairs; individual source and execution review pending.',
                existing='Historical checkpoint evidence only; not yet mapped to this exact criterion.',
                verification='Not yet performed.', live='Not yet performed.', root_cause='Pending assessment',
                remediation='Inspect exact contract and exercise customer behavior.', blocker='Current audit pending', priority='P1'))
    return rows


def render(rows):
    lines = ['# Intent Radar Phase 2/3 requirement-level audit', '',
        'Baseline: 2026-11-11, HEAD `03398f62a3c040e2220157fd7726d7c1233c6969` plus preserved source checkpoint.',
        'The original restartable checklist P2-A–E/P3-A–E is expanded using every detailed acceptance criterion in the owner request. No separate original detailed master document was found. IDs remain stable; historical reports are preserved.', '',
        'Each record includes expected behavior, implementation, backend/frontend, API, storage, historical evidence, new verification, live acceptance, status, cause, repair, blocker and priority. Initial statuses are explicitly unverified, not claims that missing features are implemented.', '',
        'Verification rule: exact implementation plus the applicable customer interaction, persistence, authorization and required live evidence must be reviewed. A suite pass never automatically verifies a row. External gates remain separate.', '']
    for group in GROUPS:
        lines += [f'## {group} — {GROUPS[group][0]}', '', '| ID / expected customer behavior | Actual / backend / frontend / API / database | Historical / new / live evidence | Status / cause / remediation / blocker / priority |', '|---|---|---|---|']
        for row in rows:
            if row['group'] != group:
                continue
            cells = [f"**{row['id']}** — {row['expected']}",
                f"{row['actual']}<br>Backend: `{row['backend']}`<br>Frontend: `{row['frontend']}`<br>API: `{row['api']}`<br>Storage: `{row['database']}`",
                f"Historical: {row['existing']}<br>New: {row['verification']}<br>Live/manual: {row['live']}",
                f"**{row['status']}**<br>Cause: {row['root_cause']}<br>Repair: {row['remediation']}<br>Blocker: {row['blocker']}<br>Priority: {row['priority']}"]
            lines.append('| ' + ' | '.join(c.replace('|', '/') for c in cells) + ' |')
        lines.append('')
    counts = Counter(r['status'] for r in rows)
    lines += ['## Reproducible counts', '', f'Total requirements: **{len(rows)}**.', '',
        '```json', json.dumps(dict(sorted(counts.items())), indent=2), '```', '',
        'Closure = VERIFIED / (total − NOT APPLICABLE). Local functional completion uses the explicit `local_complete` review field; partial/missing and unperformed independent-evaluation rows receive no credit. External approval rows are excluded only from the local-function denominator and remain in the closure denominator. Neither metric is a test-pass rate. Counts and exact numerators/denominators: `INTENT_RADAR_PHASE_2_3_AUDIT_COUNTS.json`. Production readiness also requires commercial, quality and staging gates.']
    return '\n'.join(lines)+'\n'


def presence():
    # Never serialize dotenv values, effective settings or process environment.
    files = {str(path.relative_to(ROOT)): dotenv_values(path, interpolate=False)
             for path in (ROOT/'.env', ROOT/'dashboard/.env.local', ROOT/'dashboard/.env') if path.is_file()}
    names = '''AUTH_GOOGLE_ID AUTH_GOOGLE_SECRET AUTH_SECRET AUTH_URL LEADENGINE_API_SIGNING_SECRET LEADENGINE_API_URL ALLOWED_USER_EMAILS DATABASE_URL DATABASE_BACKEND INTENT_RADAR_STAGE INTENT_RADAR_INTERNAL_WORKSPACES INTENT_RADAR_STACKEXCHANGE_ENABLED INTENT_RADAR_STACKEXCHANGE_KEY INTENT_RADAR_STACKEXCHANGE_SITES INTENT_RADAR_APPROVED_FEED_HOSTS INTENT_RADAR_SCHEDULES_ENABLED INTENT_RADAR_MIN_SCHEDULE_HOURS INTENT_RADAR_AI_ENABLED INTENT_RADAR_AI_DAILY_CALLS INTENT_RADAR_AI_DAILY_TOKENS AI_PRIMARY_PROVIDER VERTEX_AI_ENABLED VERTEX_AI_PROJECT_ID VERTEX_AI_LOCATION VERTEX_AI_MODEL GOOGLE_APPLICATION_CREDENTIALS GEMINI_API_ENABLED GEMINI_API_KEY GEMINI_MODEL AI_FALLBACK_ENABLED HEYSOW_DEVELOPER_API_ENABLED HEYSOW_MCP_ENABLED MCP_ALLOWED_HOSTS MCP_ALLOWED_ORIGINS HEYSOW_CUSTOMER_INTEGRATIONS_ENABLED HEYSOW_CUSTOMER_GMAIL_ENABLED HEYSOW_CUSTOMER_GMAIL_REDIRECT_URI HEYSOW_INTEGRATION_ENCRYPTION_KEY HEYSOW_CUSTOMER_MAIL_SENDING_ENABLED HEYSOW_CUSTOMER_MAIL_LIVE_APPROVED HEYSOW_CUSTOMER_MAIL_MODE HEYSOW_CUSTOMER_MAIL_TEST_RECIPIENT GCP_PROJECT_ID GCP_REGION SCAN_EXECUTOR LEADENGINE_CLOUD_RUN_JOB ACQUISITION_CLOUD_RUN_JOB R2_ENDPOINT R2_ACCESS_KEY_ID R2_SECRET_ACCESS_KEY R2_BUCKET_NAME R2_REGION UPSTASH_REDIS_REST_URL UPSTASH_REDIS_REST_TOKEN'''.split()
    return [{'name': name, 'process_presence': bool(os.environ.get(name)),
        'files_with_nonempty_value': [file for file, values in files.items() if values.get(name)]}
        for name in names]


if __name__ == '__main__':
    path = ROOT/'docs/INTENT_RADAR_PHASE_2_3_REQUIREMENTS_AUDIT.json'
    rows = json.loads(path.read_text()) if path.exists() else inventory()
    path.write_text(json.dumps(rows, indent=2)+'\n')
    (ROOT/'docs/INTENT_RADAR_PHASE_2_3_REQUIREMENTS_AUDIT.md').write_text(render(rows))
    values = presence()
    (ROOT/'docs/PLANEBYTE_LAUNCH_CONFIGURATION_PRESENCE.json').write_text(json.dumps(values, indent=2)+'\n')
    print(json.dumps({'requirements': len(rows), 'statuses': dict(Counter(r['status'] for r in rows)),
        'presence': values}, indent=2))
